const LOCAL=APP_CONFIG.storageMode==='local';
const storageScope=LOCAL?':'+new URL('.',import.meta.url).pathname:'';
const CACHE='unitcart.tracker.v2'+storageScope, LEGACY='unitcart.v1'+storageScope;
const app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M3 3v18h18M6 15l4-5 4 3 6-8',camera:'M3 7h4l2-3h6l2 3h4v14H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',box:'m3 7 9-4 9 4v13H3zM3 7h18M8 11h8M8 15h5',bottle:'M9 3h6v4l3 4v10H6V11l3-4zM6 13h12M10 3V1h8',check:'m5 12 4 4L19 6',edit:'m15 4 5 5M3 21l2-7L16 3l5 5L10 19z',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z',close:'m6 6 12 12M18 6 6 18',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',sync:'M3 11a9 9 0 0 1 15-6l3 3M21 3v5h-5M21 13a9 9 0 0 1-15 6l-3-3M3 21v-5h5',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',external:'M14 3h7v7M21 3l-9 9M10 4H3v17h17v-7',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sheet:'M5 3h10l5 5v13H5zM15 3v6h5M8 12h9M8 16h9M12 12v7'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[n]||paths.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(v,d=0)=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:d})+'원':'—';
const num=v=>v===''||v==null?null:Number(v);
const fmt=v=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
const stamp=()=>new Date().toISOString();
const uid=p=>p+'-'+crypto.randomUUID();
const koreanDate=v=>v?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v)):'기록 없음';
const dayOf=v=>v?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v)):'';
const dateIso=d=>d===today()?stamp():new Date(d+'T00:00:00+09:00').toISOString();
const daysSince=v=>v?Math.floor((Date.now()-new Date(v).getTime())/86400000):Infinity;
const units=['개','100g','100mL','m'];
const categories=['주방·세탁','화장지·물티슈','욕실·위생','육아용품','식품·음료','기타'];
const marketClass=p=>p==='코스트코'?'costco':p==='네이버'?'naver':'coupang';
const pill=p=>`<span class="market-pill ${marketClass(p)}">${esc(p==='네이버'?'네이버 공식몰':p)}</span>`;
const a=(url,text,cls='button')=>`<a class="${cls}" href="${esc(url)}" target="${url.startsWith('https://search.naver.com/')?'_self':'_blank'}" rel="noopener noreferrer">${text}</a>`;
let state=emptyState(),page='watch',selectedId=null,filter='all',search='',sourceFilter='',range='all';
let cloudPhase='loading',cloudMessage='',localError='',cacheCorrupt=false,loaded=false,revision=0,dirty=false,syncTask=null,editSeq=0;
let photoDraft=null,legacyAvailable=false;
let onlineFeed=null, feedFailure=false;
try{const cached=localStorage.getItem(CACHE);if(cached)state=validateState(JSON.parse(cached));}catch(err){cacheCorrupt=true;localError='이 기기의 저장 데이터를 읽지 못했습니다. 데이터 화면에서 원본을 내보낸 뒤 확인해 주세요.';}
try{const old=JSON.parse(localStorage.getItem(LEGACY)||'null');legacyAvailable=!!old?.products?.some(p=>!p.isExample);}catch{}

function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function cache(){if(cacheCorrupt)return;try{localStorage.setItem(CACHE,JSON.stringify(state));localError='';}catch{localError=LOCAL?'이 브라우저에 저장하지 못했습니다. 화면을 닫기 전에 JSON으로 백업해 주세요.':'기기 저장 공간이 부족합니다. 서버 저장 상태를 확인하고 JSON으로 백업해 주세요.';}}
function commit(next){if(cacheCorrupt)throw new Error('기존 저장 데이터를 읽지 못해 덮어쓰기를 중단했습니다. 데이터 화면에서 원본을 백업해 주세요.');if(LOCAL){const stored=localStorage.getItem(CACHE);if(stored)next=mergeStates(validateState(JSON.parse(stored)),next);}state=validateState(next);editSeq++;dirty=true;cache();render();void synchronize();}
function syncView(){document.querySelectorAll('[data-sync]').forEach(el=>{el.className='sync-state '+(['saved','local'].includes(cloudPhase)?'ok':cloudPhase==='error'?'error':'');el.textContent=cloudPhase==='local'?'이 기기에 저장됨':cloudPhase==='saved'?'서버 저장됨':cloudPhase==='saving'?'저장 중':cloudPhase==='error'?(LOCAL?'기기 저장 실패':'기기에 보관 중'):'서버 연결 중';});const message=document.querySelector('#sync-detail');if(message)message.textContent=cloudMessage;}
async function request(url,options={}){const response=await fetch(new URL(url.replace(/^\//,''),import.meta.url),{...options,cache:'no-store',signal:AbortSignal.timeout(20000)});let body;try{body=await response.json();}catch{throw new Error('서버 연결을 확인해 주세요. 로그인이 필요하면 사이트를 새로 열어 주세요.');}return {response,body};}
async function synchronize(){
  if(LOCAL){loaded=true;dirty=false;cloudPhase=localError?'error':'local';cloudMessage=localError||'이 브라우저에 기록을 저장합니다. GitHub에는 가격 기록이나 사진을 보내지 않습니다. 다른 기기에는 JSON 백업을 가져오세요.';syncView();return;}
  if(syncTask)return syncTask;
  syncTask=(async()=>{
    cloudPhase='saving';syncView();
    try{
      if(!loaded){const {response,body}=await request('/api/tracker');if(!response.ok)throw new Error(body.error||'서버 기록을 읽지 못했습니다.');const remote=validateState(body.state);state=mergeStates(remote,state);revision=body.revision;loaded=true;dirty=JSON.stringify(remote)!==JSON.stringify(state);cache();render();}
      for(let attempts=0;dirty&&attempts<5;attempts++){
        const sequence=editSeq,snapshot=structuredClone(state);
        const {response,body}=await request('/api/tracker',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRevision:revision,state:snapshot})});
        if(response.status===409){state=mergeStates(validateState(body.state),state);revision=body.revision;cache();render();continue;}
        if(!response.ok)throw new Error(body.error||'서버 저장에 실패했습니다.');
        revision=body.revision;
        if(body.state)state=mergeStates(validateState(body.state),state);
        dirty=editSeq!==sequence;cache();
      }
      if(dirty)throw new Error('다른 기기의 수정과 겹쳤습니다. 잠시 뒤 다시 저장해 주세요.');
      cloudPhase='saved';cloudMessage='서버에 저장했습니다. 같은 계정으로 휴대폰과 PC에서 열 수 있습니다.';
    }catch(err){cloudPhase='error';cloudMessage=(err.message||'서버에 연결하지 못했습니다.')+' 기기에 보관한 변경은 연결 후 다시 저장합니다.';}
    finally{syncTask=null;syncView();}
  })();return syncTask;
}
window.addEventListener('online',()=>{void synchronize();});
window.addEventListener('storage',e=>{if(!LOCAL||e.key!==CACHE||!e.newValue)return;try{const merged=mergeStates(state,validateState(JSON.parse(e.newValue)));if(JSON.stringify(merged)!==JSON.stringify(state)){state=merged;cache();render();}}catch(err){toast(err.message);}});
document.addEventListener('visibilitychange',()=>{if(!LOCAL&&document.visibilityState==='visible'&&loaded&&!syncTask){loaded=false;void synchronize();}});

function liveItems(){return state.items.filter(i=>filter==='archived'?i.archived:!i.archived);}
function sourcesFor(id,includeArchived=false){return state.sources.filter(s=>s.itemId===id&&(includeArchived||!s.archived));}
function current(){const visible=sortedItems();return visible.find(i=>i.id===selectedId)||visible[0]||null;}
function summary(s){return sourceSummary(s,state.observations);}
function hasTarget(item){return sourcesFor(item.id).some(s=>summary(s).targetReached);}
function needsRecord(item){return sourcesFor(item.id).length===0||sourcesFor(item.id).some(s=>!summary(s).latest||daysSince(summary(s).latest.observedAt)>=7);}
function sortedItems(){return liveItems().filter(i=>(filter!=='favorite'||i.favorite)&&(filter!=='target'||hasTarget(i))&&[i.name,i.brand,i.variant,i.sku].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.name.localeCompare(b.name,'ko'));}
function header(){return `<aside class="sidebar"><a class="logo" href="#" data-act="page" data-page="watch"><img src="./icon.svg" alt=""><span>한눈단가</span></a><div class="brand-sub">우리 집 생필품 가격 기록</div><nav class="nav" aria-label="주 메뉴">${[['watch','grid','내 생필품'],['online','sync','쇼핑몰 가격'],['history','chart','전체 가격 기록'],['data','sheet','데이터 · 백업']].map(([key,image,label])=>`<button data-act="page" data-page="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(image)}<span>${label}</span></button>`).join('')}</nav><div class="side-note">${icon('shield')}${SHARED_API?'<a href="./shared.html">공동 가격표 열기</a>':''}<strong>같은 상품을, 꾸준히</strong>코스트코·쿠팡·네이버 가격을<br>날짜별로 모아 두세요.<br><br>${APP_CONFIG.legacyComparison?'<a href="./compare.html">기존 가격 비교표</a>':''}</div></aside><div class="layout"><header class="topbar"><a class="brand-mini" href="./tracker.html"><img src="./icon.svg" alt="">한눈단가</a><div class="breadcrumb"><span>우리 집 장보기</span><span>/</span><strong>${{watch:'내 생필품',online:'쇼핑몰 가격',history:'전체 가격 기록',data:'데이터 · 백업'}[page]}</strong></div><div class="top-right">${SHARED_API?'<a class="text-button" href="./shared.html">공동 가격표</a>':''}<span data-sync class="sync-state">서버 연결 중</span>${LOCAL?'':`<button class="icon-button" data-act="sync" aria-label="서버 기록 새로고침">${icon('sync')}</button>`}</div></header>${localError?`<div class="wide-alert" role="alert">${esc(localError)}</div>`:''}<main id="main"><nav class="mobile-nav" aria-label="모바일 메뉴">${[['watch','내 생필품'],['online','쇼핑몰 가격'],['history','전체 기록'],['data','백업']].map(([k,v])=>`<button data-act="page" data-page="${k}" class="${page===k?'active':''}">${v}</button>`).join('')}</nav>`;}
function intro(){const active=state.items.filter(i=>!i.archived),count=state.observations.filter(o=>!o.deletedAt).length;return `<div class="page-head"><div><div class="eyebrow">MY HOUSEHOLD ESSENTIALS</div><h1>늘 사는 생필품, 가격은 기억해 두세요.</h1><p>한 번 등록하고, 장볼 때마다 가격만 쌓아 가세요.</p></div><div class="actions page-actions"><button class="button primary" data-act="photo">${icon('camera')}가격표 사진 읽기</button><button class="button" data-act="add-item">${icon('plus')}상품 등록</button></div></div><section class="summary-grid" aria-label="가격 기록 현황"><div class="metric"><span class="metric-label">추적 중인 생필품</span><div class="metric-icon">${icon('box')}</div><div class="metric-value">${active.length}<span>개</span></div><div class="metric-sub">정해 둔 상품을 반복 기록</div></div><div class="metric"><span class="metric-label">쌓인 가격 기록</span><div class="metric-icon">${icon('chart')}</div><div class="metric-value">${count}<span>건</span></div><div class="metric-sub">수정해도 이전 이력 보존</div></div><div class="metric"><span class="metric-label">마지막 기록이 목표가 이하</span><div class="metric-icon">${icon('check')}</div><div class="metric-value">${active.filter(hasTarget).length}<span>개</span></div><div class="metric-sub">기록된 가격 기준</div></div></section><div class="tracking-notice">${icon('info')}<p><strong>코스트코 매장 · 쿠팡 로켓 우선 · 네이버 공식몰</strong><br>내가 기록한 매장·판매처 가격도 계속 비교할 수 있습니다. 온라인 자동 수집 현황은 아래 표에서 확인하세요.</p></div>`;}
function watchList(){const items=sortedItems(),item=current();return `<section class="panel watch-panel"><div class="panel-head"><h2>나의 고정 상품</h2><span class="meta">${items.length}개</span></div><label class="watch-search">${icon('search')}<input id="watch-search" type="search" value="${esc(search)}" placeholder="제품명 · 품목번호" aria-label="고정 상품 검색"></label><div class="watch-filter">${[['all','전체'],['favorite','즐겨찾기'],['target','목표가 이하'],['archived','보관']].map(([k,v])=>`<button class="chip ${filter===k?'active':''}" data-act="filter" data-filter="${k}">${v}</button>`).join('')}</div><div class="watch-items" id="watch-items">${items.length?items.map(i=>{const ss=sourcesFor(i.id).map(summary),latest=ss.map(s=>s.latest).filter(Boolean).sort((a,b)=>b.observedAt.localeCompare(a.observedAt))[0];return `<button class="watch-item ${item?.id===i.id?'selected':''}" data-act="select" data-id="${esc(i.id)}" aria-pressed="${item?.id===i.id}"><span class="watch-art">${icon(i.unit==='100mL'?'bottle':'box')}</span><span><strong>${esc(i.name)}</strong><small>${esc(i.variant||i.category)}</small><small class="price-label">${latest?koreanDate(latest.observedAt)+' 기록':'첫 가격을 기록해 주세요'}</small></span><span class="star-mark ${i.favorite?'on':''}">${i.favorite?'★':'☆'}</span></button>`;}).join(''):`<div class="empty-state"><p>${search?'일치하는 상품이 없어요.':filter==='target'?'목표가 이하인 기록이 아직 없어요.':'등록된 상품이 없어요.'}</p></div>`}</div><div class="watch-footer">같은 브랜드·제품라인·향을 하나의 상품으로 관리합니다. 용량과 판매처별 가격은 따로 쌓입니다.</div></section>`;}
function blank(){return `<section class="panel big-empty"><div class="empty-illustration">${icon('box')}</div><h2>우리 집에서 늘 쓰는 상품부터</h2><p>제품명과 규격을 한 번만 등록하세요.<br>다음 장보기부터는 사진이나 가격만 추가하면 됩니다.</p><div class="actions"><button class="button primary" data-act="photo">${icon('camera')}첫 가격표 읽기</button><button class="button" data-act="add-item">직접 등록</button></div><div class="quick-categories">${['세탁세제','주방세제','화장지','물티슈','샴푸'].map(n=>`<button data-act="quick-item" data-name="${n}">${n} 등록</button>`).join('')}</div><p class="empty-caption">예시 가격은 넣지 않았습니다. 실제 사용하는 브랜드를 입력해 주세요.</p>${legacyAvailable?'<button class="text-button" data-act="legacy-import" style="margin-top:20px">이전에 등록한 실제 상품 가져오기</button>':''}</section>`;}
function sourceCard(source,item){const s=summary(source),last=s.latest,low=s.lowest,change=s.changePercent;return `<article class="panel source-card"><div class="pill-row">${pill(source.platform)}${source.platform==='쿠팡'?`<span class="mini-tag ${['로켓배송','로켓프레시'].includes(last?.delivery)?'rocket':''}">${esc(last?.delivery||source.delivery||'미확인')}</span>`:''}${last&&daysSince(last.observedAt)>=7?'<span class="mini-tag warn">다시 확인</span>':''}${s.targetReached?'<span class="mini-tag good">마지막 기록 목표가 이하</span>':''}</div><h3>${esc(source.platform==='코스트코'?source.store||'코스트코 매장':source.seller)}</h3><div class="source-sub">${esc(source.variant)} · 총 ${fmt(source.quantity)}${rawUnit(source.unit)}</div><div class="source-price"><strong>${money(last?.price)}</strong><span>${last?'상품가격':'기록 전'}</span></div><div class="source-sub">${last?.unitPrice!=null?money(last.unitPrice,2)+' / '+esc(source.unit)+' · 배송비 포함':last?.productUnitPrice!=null?money(last.productUnitPrice,2)+' / '+esc(source.unit)+' · 상품가격 기준 (최종 비교 보류)':last?'가격·총량 확인 필요':'첫 가격을 남겨 주세요'}</div><div class="source-metrics"><div><span>지난 기록 대비</span><b class="${change<0?'price-down':change>0?'price-up':''}">${change==null?'—':(change>0?'+':'')+change.toFixed(1)+'%'}</b></div><div><span>기록 이후 최저 단가</span><b>${low?money(low.unitPrice,2)+' / '+esc(source.unit):'—'}</b></div></div>${source.targetUnitPrice!=null?`<div class="target-line ${s.targetReached?'hit':''}">목표 ${money(source.targetUnitPrice,2)} / ${esc(source.unit)}${s.targetReached?' · 마지막 기록에서 도달':''}</div>`:''}<div class="source-controls"><button class="button ${source.platform==='코스트코'?'primary':''}" data-act="record" data-source="${esc(source.id)}">${icon('plus')}가격 기록</button>${source.platform==='코스트코'?`<button class="button" data-act="photo-source" data-source="${esc(source.id)}">${icon('camera')}사진</button>`:a(source.url,'상품 열기') }<button class="button" data-act="source-settings" data-source="${esc(source.id)}">설정</button></div><div class="source-time">${last?koreanDate(last.observedAt)+' 확인 · '+s.count+'회 기록':'가격 기록 없음'}${source.platform!=='코스트코'?' · 개인 기록':''}</div>${source.platform==='쿠팡'&&last&&last.delivery==='미확인'?'<div class="source-note">배송 유형 미확인 · 우선 조건 비교에서 제외</div>':''}${last?.issues?.length?`<div class="source-note">${esc(last.issues.join(' · '))}</div>`:''}</article>`;}
function itemSearchLinks(item) {
  const query = [item.brand, item.name, item.variant].filter(Boolean).join(' ');
  return {coupang: searchLinks({name:query}).coupang, naver: searchLinks({name:item.name}).naver};
}
function detail(item){const srcs=sourcesFor(item.id),links=itemSearchLinks(item);return `<div class="detail"><section class="panel item-hero"><div class="item-title"><div><div class="pill-row"><span class="mini-tag">${esc(item.category)}</span>${item.sku?`<span class="mini-tag">품목 ${esc(item.sku)}</span>`:''}${item.archived?'<span class="mini-tag">보관한 상품</span>':''}</div><h2>${esc(item.name)}</h2><div class="meta">${esc([item.brand,item.variant].filter(Boolean).join(' · ')||'제품라인·향 등 규격을 등록해 주세요.')}</div></div><div class="item-tools"><button class="icon-button" data-act="favorite" data-id="${esc(item.id)}" aria-label="${item.favorite?'즐겨찾기 해제':'즐겨찾기 추가'}" aria-pressed="${item.favorite}">${icon('star')}</button><button class="icon-button" data-act="edit-item" data-id="${esc(item.id)}" aria-label="상품 정보 수정">${icon('edit')}</button></div></div><div class="item-actions"><button class="button" data-act="add-source" data-platform="코스트코" data-id="${esc(item.id)}">${icon('plus')}코스트코 매장·규격</button><button class="button" data-act="add-source" data-platform="네이버" data-id="${esc(item.id)}">${icon('plus')}네이버 공식몰 등록</button><button class="button" data-act="add-source" data-platform="쿠팡" data-id="${esc(item.id)}">${icon('plus')}쿠팡 상품 등록</button>${a(links.naver,icon('search')+'네이버에서 검색')}${a(links.coupang,icon('search')+'쿠팡에서 찾기')}</div></section><div class="source-grid">${srcs.map(s=>sourceCard(s,item)).join('')}${!srcs.some(s=>s.platform==='네이버')?`<div class="source-empty">${icon('search')}<strong>공식몰 상품을 한 번 연결하세요</strong><p>네이버에서 같은 제품을 찾고 상품 링크·옵션·총량을 등록하세요. 이후에는 해당 판매처의 가격만 기록합니다.</p><button class="button" data-act="add-source" data-platform="네이버" data-id="${esc(item.id)}">네이버 공식몰 등록</button></div>`:''}${!srcs.some(s=>s.platform==='쿠팡')?`<div class="source-empty">${icon('box')}<strong>쿠팡은 로켓배송 우선으로</strong><p>같은 상품의 판매처·옵션·배송 유형을 등록하세요. 로켓프레시도 로켓배송과 같은 우선순위로 비교합니다.</p><button class="button" data-act="add-source" data-platform="쿠팡" data-id="${esc(item.id)}">쿠팡 상품 등록</button></div>`:''}${!srcs.some(s=>s.platform==='코스트코')?`<div class="source-empty">${icon('camera')}<strong>코스트코의 첫 가격을 남겨 보세요</strong><p>매장과 포장 수량을 정해 두면 다음부터 같은 이력에 기록할 수 있어요.</p><button class="button" data-act="add-source" data-platform="코스트코" data-id="${esc(item.id)}">코스트코 가격 등록</button></div>`:''}</div>${comparisonNote(item)}${archivedSources(item)}${chart(item)}${historyTable(item.id,12)}</div>`;}
function comparisonNote(item){
  const sources=sourcesFor(item.id),comparison=compareTrackedSources(sources,state.observations);
  if(!sources.some(s=>summary(s).latest))return '';
  const entries=[['costco','코스트코','매장별 기록'],['coupang','쿠팡','로켓배송 우선'],['naver','네이버','공식몰 확인 상품']];
  const comparable=entries.map(([key])=>comparison[key]).filter(Boolean);
  const low=comparison.lowest?.observation.unitPrice;
  const winners=comparable.filter(x=>Math.abs(x.observation.unitPrice-low)<.000001);
  const preferred=comparison.coupang,cheapest=comparison.coupangLowest;
  const cheaperOther=preferred&&cheapest&&cheapest.observation.unitPrice<preferred.observation.unitPrice-.000001;
  return `<section class="panel comparison-panel"><div class="section-heading"><div><h2>마지막 확인 가격 비교</h2><p>등록한 판매처별 최신 기록 · ${esc(item.unit)}당 결제금액</p></div></div><div class="comparison-grid">${entries.map(([key,label,hint])=>{const value=comparison[key],winner=value&&comparable.length>1&&winners.includes(value);return `<div class="comparison-cell ${winner?'best':''}">${pill(label)}<div class="comparison-hint">${hint}</div><strong>${money(value?.observation.unitPrice,2)}<span> / ${esc(item.unit)}</span></strong>${value?`<small>${esc(value.source.store||value.source.seller)}${key==='coupang'?' · '+esc(value.observation.delivery):''}</small><small>${esc(value.source.variant)}</small><small>${koreanDate(value.observation.observedAt)} 확인</small>`:'<small>비교 가능한 기록이 없어요</small>'}${winner?`<b class="comparison-best">${winners.length>1?'우선 조건 내 최저 · 동률':'우선 조건 내 최저'}</b>`:''}</div>`;}).join('')}</div>${cheaperOther?`<div class="comparison-alternative"><strong>배송 우선순위와 별도로 더 싼 쿠팡 기록이 있어요.</strong><br>${esc(cheapest.source.seller)} · ${esc(cheapest.observation.delivery)} · ${money(cheapest.observation.unitPrice,2)} / ${esc(item.unit)} (${koreanDate(cheapest.observation.observedAt)})${a(cheapest.source.url,'상품 확인','text-button')}</div>`:''}<p class="comparison-rule">쿠팡은 로켓배송·로켓프레시 → 판매자로켓 → 일반배송 순으로 고르고, 같은 순위에서 단가를 비교합니다. 배송 유형·배송비·재고를 확인하지 않은 기록은 비교에서 제외합니다. 각 날짜에 확인한 가격이며 현재 판매가격은 상품 페이지에서 확인하세요.</p></section>`;
}
function archivedSources(item){const saved=state.sources.filter(s=>s.itemId===item.id&&s.archived);return saved.length?`<details class="panel" style="padding:16px 20px;margin-bottom:18px"><summary>보관한 판매처 · 규격 ${saved.length}개</summary><div class="candidate-list" style="margin-top:14px">${saved.map(s=>`<div class="candidate"><span><b>${esc(s.platform+' · '+(s.store||s.seller))}</b><br>${esc(s.variant)}</span><button class="button" data-act="restore-source" data-source="${esc(s.id)}">다시 추적</button></div>`).join('')}</div></details>`:'';}
function chart(item){const srcs=sourcesFor(item.id),colors=['#7560d2','#27a566','#4096d2','#cc8d35','#b5609d'],cutoff=range==='all'?0:Date.now()-Number(range)*86400000;const sets=srcs.map((s,i)=>({s,color:s.platform==='코스트코'?colors[(i*2)%colors.length]:s.platform==='네이버'?'#279b5b':colors[(i+2)%colors.length],points:historySeries(s,state.observations).filter(o=>o.unitPrice!=null&&new Date(o.observedAt).getTime()>=cutoff)})).filter(s=>s.points.length);const all=sets.flatMap(s=>s.points),controls=`<select id="chart-range" class="history-filter" aria-label="차트 기간">${[['all','전체 기간'],['30','최근 30일'],['90','최근 90일']].map(([k,v])=>`<option value="${k}" ${k===range?'selected':''}>${v}</option>`).join('')}</select>`;
  let plot='';if(!all.length)plot=`<div class="chart-empty"><div>${icon('chart')}<p>기록이 쌓이면 가격 변화를 보여드려요.<br><small>배송비와 재고가 확인된 같은 단위의 가격을 표시합니다.</small></p></div></div>`;else{const W=680,H=245,L=75,R=18,T=14,B=36;let min=Math.min(...all.map(o=>o.unitPrice)),max=Math.max(...all.map(o=>o.unitPrice));const padding=Math.max((max-min)*.18,max*.05,1);min=Math.max(0,min-padding);max+=padding;let tmin=Math.min(...all.map(o=>Date.parse(o.observedAt))),tmax=Math.max(...all.map(o=>Date.parse(o.observedAt)));if(tmin===tmax){tmin-=86400000;tmax+=86400000;}const x=o=>L+(Date.parse(o.observedAt)-tmin)/(tmax-tmin)*(W-L-R),y=p=>T+(1-(p-min)/(max-min))*(H-T-B);const ticks=[min,(min+max)/2,max];plot=`<div class="chart-legend">${sets.map(d=>`<span><i class="legend-line" style="background:${d.color}"></i>${esc(d.s.platform+' · '+(d.s.store||d.s.seller)+' · '+d.s.variant)}</span>`).join('')}</div><svg class="price-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(item.name)}의 ${esc(item.unit)}당 가격 이력"><title>저장된 판매처별 가격 이력. 표에서 정확한 값을 볼 수 있습니다.</title>${ticks.map(v=>`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#e9eaf2" stroke-dasharray="4 4"/><text class="chart-label" x="${L-10}" y="${y(v)+4}" text-anchor="end">${fmt(Math.round(v*100)/100)}</text>`).join('')}${sets.map(d=>`<polyline fill="none" stroke="${d.color}" stroke-width="2.5" stroke-linejoin="round" points="${d.points.map(o=>x(o)+','+y(o.unitPrice)).join(' ')}"/>${d.points.map(o=>`<circle cx="${x(o)}" cy="${y(o.unitPrice)}" r="4" fill="white" stroke="${d.color}" stroke-width="2"><title>${esc(d.s.platform+' '+koreanDate(o.observedAt)+' '+money(o.unitPrice,2)+' / '+item.unit)}</title></circle>`).join('')}`).join('')}<text class="chart-label" x="${L}" y="${H-8}">${esc(koreanDate(new Date(tmin).toISOString()))}</text><text class="chart-label" x="${W-R}" y="${H-8}" text-anchor="end">${esc(koreanDate(new Date(tmax).toISOString()))}</text></svg>`;}
  return `<section class="panel chart-panel"><div class="section-heading"><div><h2>같은 양으로 보는 가격 변화</h2><p>${esc(item.unit)}당 결제금액 · 확인한 가격만 표시</p></div>${controls}</div>${plot}<div class="chart-foot">코스트코 매장별·쿠팡과 네이버의 판매처·옵션별로 이력을 구분합니다. 선 사이의 날짜에는 가격을 조회하거나 추정하지 않았습니다.</div></section>`;
}
function historyTable(itemId=null,limit=200){let rows=state.observations.filter(o=>!o.deletedAt&&(!itemId||o.itemId===itemId)&&(!sourceFilter||itemId||o.sourceId===sourceFilter)).sort((a,b)=>b.observedAt.localeCompare(a.observedAt)||b.createdAt.localeCompare(a.createdAt));const total=rows.length;rows=rows.slice(0,limit);return `<section class="panel history-panel"><div class="section-heading"><div><h2>${itemId?'이 상품의 최근 기록':'날짜별 가격 기록'}</h2><p>${total}건 · 잘못 입력한 기록은 제외할 수 있어요.</p></div>${itemId?'<button class="text-button" data-act="page" data-page="history">전체 기록</button>':''}</div><div class="history-table-wrap"><table class="history-table"><thead><tr><th>확인일 · 상품</th><th>판매처 · 옵션</th><th>상품가격</th><th>배송비</th><th>단가</th><th>관리</th></tr></thead><tbody>${rows.length?rows.map(o=>{const s=state.sources.find(s=>s.id===o.sourceId),i=state.items.find(i=>i.id===o.itemId),m=observationMetrics(o);return `<tr><td>${esc(koreanDate(o.observedAt))}<small>${esc(i?.name)}${o.method==='photo'?' · 사진 확인':o.method==='migration'?' · 이전 기록':''}</small></td><td>${pill(s.platform)}<small>${esc((s.store||s.seller)+' · '+s.variant)}${s.platform==='쿠팡'?' · '+esc(o.delivery||'배송 미확인'):''}</small></td><td class="money">${money(o.price)}<small>${o.discount?'확인 할인 '+money(o.discount):''}${o.note?' '+esc(o.note):''}</small></td><td>${o.shipping==null?'미확인':money(o.shipping)}</td><td class="money">${money(m.unitPrice??m.productUnitPrice,2)}<small>${esc(o.unit)}당 · ${m.unitPrice==null&&m.productUnitPrice!=null?'상품가격 기준 / 최종 비교 보류':'배송비 포함'}${m.issues?.length?' · '+esc(m.issues.join(' · ')):''}</small></td><td><button class="text-button danger-link" data-act="remove-observation" data-id="${esc(o.id)}">제외</button></td></tr>`;}).join(''):'<tr><td colspan="6" style="text-align:center;padding:35px;color:#85869a">아직 저장한 가격이 없습니다.</td></tr>'}</tbody></table></div>${total>limit?`<div class="table-more">최근 ${limit}건을 표시합니다. 전체 이력은 CSV로 내보낼 수 있어요.</div>`:''}</section>`;}
function historyPage(){return `<div class="page-head"><div><div class="eyebrow">PRICE JOURNAL</div><h1>쌓아 둔 가격이 다음 장보기의 기준.</h1><p>지난 가격을 지우지 않고 날짜별로 비교하세요.</p></div><button class="button" data-act="export-csv">${icon('download')}시트용 CSV</button></div><div class="tracking-summary"><select class="history-filter" id="source-filter" aria-label="판매처별 기록 필터"><option value="">모든 상품 · 판매처</option>${state.sources.map(s=>`<option value="${esc(s.id)}" ${sourceFilter===s.id?'selected':''}>${esc(state.items.find(i=>i.id===s.itemId)?.name+' · '+s.platform+' · '+s.variant)}</option>`).join('')}</select></div>${historyTable()}`;}
function dataPage(){return `<div class="page-head"><div><div class="eyebrow">MY DATA</div><h1>가격 기록을 안전하게 보관하세요.</h1><p>${LOCAL?'이 브라우저에 기록하고, JSON 백업으로 다른 기기에 옮길 수 있어요.':'서버에 저장하고, 필요할 때 구글 시트나 엑셀로 가져갈 수 있어요.'}</p></div></div><div class="data-grid"><section class="panel data-card"><h2>${LOCAL?'이 기기의 저장 상태':'저장 상태'}</h2><p id="sync-detail">${esc(cloudMessage||(LOCAL?'이 브라우저에 저장합니다.':'서버 기록과 연결하고 있습니다.'))}</p><div class="actions">${LOCAL?'<button class="button" data-act="copy-app-link">앱 링크 복사</button>':`<button class="button" data-act="sync">${icon('sync')}서버와 다시 연결</button>`}<button class="button primary" data-act="export-json">${icon('download')}전체 JSON 백업</button></div><p class="meta" style="margin-top:16px">${LOCAL?'앱 링크로 화면을 공유할 수 있습니다. 방문자별 기록은 각 브라우저에 따로 저장됩니다. 기기·브라우저를 바꾸거나 사이트 데이터를 지우기 전 JSON으로 백업하세요. 가격과 사진은 GitHub에 업로드하지 않습니다.':'새 기기에서는 같은 ChatGPT 계정으로 사이트를 여세요. 오프라인 변경은 이 기기에 보관한 뒤 연결되면 저장합니다.'}</p></section><section class="panel data-card"><h2>구글 시트 · 엑셀용 가격 이력</h2><p>확인일, 상품, 매장·판매처, 선택 옵션, 쿠팡 배송 유형, 상품가격, 배송비, 총량과 단가를 한 행씩 내보냅니다.</p><button class="button primary" data-act="export-csv">${icon('sheet')}전체 이력 CSV 내려받기</button><p class="meta" style="margin-top:16px">구글 시트의 파일 › 가져오기 › 업로드에서 여세요. CSV는 내려받은 시점의 기록이며 자동 동기화되지는 않습니다.</p></section><section class="panel data-card"><h2>이전 기록 · 백업 가져오기</h2><p>기존 한눈단가의 실제 상품과 확인된 가격 또는 새 가격 이력 JSON을 합칩니다. 같은 기록은 한 번만 추가합니다.</p><div class="actions"><label class="button import-file">JSON 파일 선택<input id="import-json" type="file" accept="application/json,.json" aria-label="가격 기록 JSON 파일 선택"></label>${legacyAvailable?'<button class="button" data-act="legacy-import">이 기기의 이전 기록 가져오기</button>':''}</div><p class="meta" style="margin-top:16px">${LOCAL?'기존 사이트의 데이터 · 백업에서 받은 JSON도 가져올 수 있어요. 백업 파일을 GitHub 저장소에 올릴 필요는 없습니다.':'이전 버전에 남아 있는 마지막 가격만 가져올 수 있습니다. 이미 덮어쓴 과거 가격은 복원할 수 없습니다.'}</p>${cacheCorrupt?'<button class="button" data-act="export-raw">읽지 못한 원본 백업</button>':''}</section><section class="panel data-card"><h2>자동 조회 상태</h2><div class="tracking-notice neutral"><p><strong>공개 상품 목록을 매일 조회합니다.</strong><br>매일 오전 7시 17분(한국시간)에 GitHub Actions가 공개 목록의 상품 페이지를 확인합니다. 조회 시각과 실패 여부는 ‘쇼핑몰 가격’에서 확인하세요. 개인 상품 링크는 이 브라우저에 보관됩니다.</p></div><p>코스트코 매장 가격은 방문해서 촬영하거나 입력한 날짜의 기록입니다. 목표가 도달 표시는 마지막으로 저장한 가격 기준입니다.</p>${APP_CONFIG.legacyComparison?'<a class="text-button" href="./compare.html">기존 코스트코·쿠팡·네이버 비교표 열기</a>':''}</section></div>`;}
function render(){const item=current();selectedId=item?.id||null;app.innerHTML=header()+(page==='online'?onlinePanel(onlineFeed,feedFailure):page==='watch'?intro()+onlinePanel(onlineFeed,feedFailure)+(liveItems().length?`<div class="board">${watchList()}${item?detail(item):blank()}</div>`:blank()):page==='history'?historyPage():dataPage())+'</main></div>';syncView();}

const options=(values,value)=>values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const field=(name,label,value='',attr='',help='')=>`<label>${label}<input name="${name}" value="${esc(value??'')}" ${attr}>${help?`<span class="help">${help}</span>`:''}</label>`;
const numeric='type="number" min="0" max="1000000000000" step="any" inputmode="decimal"';
const autoQuantityNotice=unit=>`<span class="help">규격(예: 80매 × 10팩)을 입력하면 총량을 제안합니다. 잘못 인식되면 직접 고쳐 주세요. 비교 기준: ${esc(unit)}.</span>`;
function unitLabel(unit){return unit==='개'?'1개당':unit==='m'?'1m당':`${unit}당`;}
function inferQuantityForForm(form){
  if (!['item-form','source-form'].includes(form?.id)) return;
  const input=form.elements.namedItem('quantity');
  const spec=form.id==='item-form'?form.elements.namedItem('pack')?.value:form.elements.namedItem('variant')?.value;
  const unit=form.id==='item-form'?form.elements.namedItem('unit')?.value:state.items.find(item=>item.id===form.dataset.item)?.unit;
  if (!input) return;
  // A value entered as pieces must not silently become grams or millilitres.
  if (input.dataset.unit && input.dataset.unit!==unit) {
    input.value='';
    input.dataset.manual='false';
    input.dataset.auto='';
  }
  input.dataset.unit=unit;
  if (input.dataset.manual==='true') return;
  const qty=suggestQuantity(spec,unit);
  input.value=qty===null?'':String(qty);
  input.dataset.auto=qty===null?'':'true';
}
function updatePreview(){
  const form=dialog.querySelector('#record-form,#item-form,#source-form');
  if(!form) return;
  const target=form.querySelector('#unit-live-preview');
  if(!target) return;
  const f=Object.fromEntries(new FormData(form));
  const s=form.id==='record-form'?state.sources.find(x=>x.id===form.dataset.source):null;
  const unit=s?.unit||(form.id==='item-form'?f.unit:state.items.find(i=>i.id===form.dataset.item)?.unit)||'개';
  const quantityInput=form.elements.namedItem('quantity');
  if (quantityInput) {
    quantityInput.dataset.unit=unit;
    const label=quantityInput.closest('label');
    if (label?.firstChild?.nodeType===3) label.firstChild.textContent='묶음 전체 총량 ('+rawUnit(unit)+')';
  }
  const quantity=s?.quantity??num(f.quantity);
  const platform=s?.platform||form.dataset.platform||'코스트코';
  const shipping=platform==='코스트코'?0:num(f.shipping);
  const values=calculateUnitPrices({price:f.price,quantity,unit,shipping,discount:num(f.discount)||0});
  const guessed=form.elements.namedItem('quantity')?.dataset.auto==='true';
  const prefix=guessed?`<div class="preview-hint">규격에서 총량을 추정했습니다. <b>${fmt(quantity)}${esc(rawUnit(unit))}</b>가 맞는지 확인하세요.</div>`:'';
  if(!(Number(f.price)>0)){
    target.innerHTML=`<strong>자동 단가 계산</strong><div>가격을 입력하면 ${esc(unitLabel(unit))} 금액이 바로 표시됩니다.</div>${prefix}`;
    return;
  }
  if(!(Number(quantity)>0)){
    target.innerHTML='<strong>자동 단가 계산</strong><div>총량을 입력하거나 포장 규격을 적으면 단가가 계산됩니다.</div>';
    return;
  }
  if(values.productUnitPrice===null){
    target.innerHTML='<strong>자동 단가 계산</strong><div>가격·할인액·총량을 확인해 주세요. 할인액은 상품가격보다 작아야 합니다.</div>';
    return;
  }
  const productText=money(values.productUnitPrice,2);
  const finalText=values.finalUnitPrice===null?'배송비 확인 후 계산':money(values.finalUnitPrice,2);
  const note=values.finalUnitPrice===null?'배송비 미확인 · 상품가격 기준 단가는 계산됨':'상품가격·할인·배송비를 반영한 최종 결제단가';
  target.innerHTML=`<div class="preview-label">자동 계산 · ${esc(unitLabel(unit))}</div><div class="preview-main">${productText}</div><div class="preview-hint">상품가격 기준 (${money(values.productTotal)} ÷ ${fmt(quantity)}${esc(rawUnit(unit))})</div><div class="preview-final"><b>배송비 포함 ${esc(unitLabel(unit))}</b><span>${finalText}</span></div><div class="preview-hint">${note}</div>${prefix}`;
}
function openForm(title,body,formId,data='',footer=''){dialog.innerHTML=`<form id="${formId}" ${data}><div class="dialog-header"><h2>${title}</h2><button class="icon-button" data-act="close" type="button" aria-label="닫기">${icon('close')}</button></div><div class="dialog-body">${body}<p class="form-error" id="form-error" role="alert"></p></div><div class="dialog-footer">${footer}<button class="button" type="button" data-act="close">취소</button><button class="button primary" type="submit">${formId==='record-form'?'가격 이력에 추가':'저장하기'}</button></div></form>`;if(!dialog.open)dialog.showModal();setTimeout(()=>dialog.querySelector('input:not([type="checkbox"]),select,textarea')?.focus(),30);}
function draftReview(d){if(!d)return '';return `<div class="draft-review">${d.photoPreview?`<img src="${d.photoPreview}" alt="확인할 가격표 사진">`:''}<strong>읽은 값은 사진과 대조해 주세요.</strong>${d.warnings?.length?`<ul>${d.warnings.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:''}${d.priceCandidates?.length>1?`<label>사진에서 찾은 가격 후보<select id="draft-price"><option value="">가격을 선택하거나 직접 입력하세요</option>${d.priceCandidates.filter(c=>c.kind!=='unit').map(c=>`<option value="${c.amount}">${money(c.amount)} · ${esc(c.label)}</option>`).join('')}</select></label>`:''}<details><summary>인식한 글자 보기</summary><pre>${esc(d.rawText)}</pre></details></div>`;}
function itemForm(id=null,draft=null,preset=''){photoDraft=draft;const item=state.items.find(i=>i.id===id),i=item||{name:draft?.name||'',brand:'',variant:'',category:preset==='세탁세제'||preset==='주방세제'?'주방·세탁':preset==='화장지'||preset==='물티슈'?'화장지·물티슈':'기타',unit:draft?.unit||'개',sku:draft?.sku||'',favorite:true};const body=`${draftReview(draft)}<div class="form-grid"><label class="full">제품명<input name="name" maxlength="200" required value="${esc(i.name)}" placeholder="${esc(preset?'브랜드 + '+preset:'예: 커클랜드 울트라클린 캡슐세제')}"></label>${field('brand','브랜드',i.brand,'maxlength="120"')}${field('sku','코스트코 품목번호 (선택)',i.sku,'maxlength="100"','다음 사진에서 같은 상품을 찾는 데 사용합니다.')}<label class="full">제품라인 · 향 · 종류<input name="variant" maxlength="300" value="${esc(i.variant)}" placeholder="예: 울트라클린 / 무향 / 캡슐형"></label><label>분류<select name="category">${options(categories,i.category)}</select></label><label>비교단위<select name="unit" ${item&&sourcesFor(item.id,true).length?'disabled':''}>${options(units,i.unit)}</select><span class="help">용량이 달라도 같은 양으로 비교합니다.</span></label><label class="check full"><input type="checkbox" name="favorite" ${i.favorite?'checked':''}>자주 사는 상품으로 고정해 두기</label>${!item?`<div class="form-section full">첫 코스트코 가격 (나중에 입력해도 돼요)</div><label class="full">포장 규격<input name="pack" maxlength="300" value="${esc(draft?.spec||'')}" placeholder="예: 120개 / 1.5L × 3개"></label>${field('quantity','묶음 전체 총량',draft?.costcoQuantity??suggestQuantity(draft?.spec||'',i.unit),numeric,'선택한 단위에 맞는 총량입니다. 예: 30개입 → 30개, 1.5L × 3병 → 4500mL')}${field('price','묶음 판매가격 (원)',draft?.costcoPrice,numeric)}<div id="unit-live-preview" class="unit-live-preview full" aria-live="polite"></div>${field('store','매장명 (선택)','','maxlength="120" placeholder="예: 양재점"')}${field('date','가격 확인일',today(),`type="date" max="${today()}" required`)}${draft?'<label class="check full record-confirm"><input name="confirmed" type="checkbox" required>사진과 상품명·실제 판매가격·총량이 같은지 확인했어요.</label>':''}`:''}</div>`;openForm(item?'고정 상품 수정':'우리 집 생필품 등록',body,'item-form',`data-id="${esc(id||'')}"`,item?`<button type="button" class="button" style="margin-right:auto" data-act="archive-item" data-id="${esc(item.id)}">${item.archived?'다시 추적':'목록에서 보관'}</button>`:'');updatePreview();}
